import React, { useState, useEffect } from 'react';
import { 
  Paper, Typography, TextField, Button, Table, TableBody, 
  TableCell, TableContainer, TableHead, TableRow, Box,
  Dialog, DialogTitle, DialogContent, DialogActions 
} from '@mui/material';
import { Add as AddIcon, Print as PrintIcon, Save as SaveIcon } from '@mui/icons-material';
import { getInvoices, createInvoice } from '../services/invoiceService';
import InvoicePreview from './InvoicePreview';

const InvoiceManager = () => {
  const [invoices, setInvoices] = useState([]);
  const [formData, setFormData] = useState({
    invoiceNumber: '',
    customerName: '',
    customerAddress: '',
    customerPhone: '',
    items: [{ description: '', quantity: 1, price: 0 }],
    subtotal: 0,
    tax: 0,
    discount: 0,
    total: 0,
    notes: ''
  });
  const [previewOpen, setPreviewOpen] = useState(false);

  useEffect(() => {
    fetchInvoices();
  }, []);

  const fetchInvoices = async () => {
    try {
      const data = await getInvoices();
      setInvoices(data);
    } catch (error) {
      console.error('Error fetching invoices:', error);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleItemChange = (index, e) => {
    const { name, value } = e.target;
    const newItems = [...formData.items];
    newItems[index][name] = name === 'quantity' || name === 'price' ? parseFloat(value) : value;
    
    const subtotal = newItems.reduce((sum, item) => sum + (item.quantity * item.price), 0);
    const taxAmount = subtotal * (formData.tax / 100);
    const total = subtotal + taxAmount - formData.discount;
    
    setFormData(prev => ({
      ...prev,
      items: newItems,
      subtotal,
      total
    }));
  };

  const addItem = () => {
    setFormData(prev => ({
      ...prev,
      items: [...prev.items, { description: '', quantity: 1, price: 0 }]
    }));
  };

  const removeItem = (index) => {
    const newItems = formData.items.filter((_, i) => i !== index);
    const subtotal = newItems.reduce((sum, item) => sum + (item.quantity * item.price), 0);
    const taxAmount = subtotal * (formData.tax / 100);
    const total = subtotal + taxAmount - formData.discount;
    
    setFormData(prev => ({
      ...prev,
      items: newItems,
      subtotal,
      total
    }));
  };

  const handlePreview = () => {
    setPreviewOpen(true);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createInvoice(formData);
      fetchInvoices();
      setFormData({
        invoiceNumber: '',
        customerName: '',
        customerAddress: '',
        customerPhone: '',
        items: [{ description: '', quantity: 1, price: 0 }],
        subtotal: 0,
        tax: 0,
        discount: 0,
        total: 0,
        notes: ''
      });
    } catch (error) {
      console.error('Error creating invoice:', error);
    }
  };

  return (
    <div>
      <Paper elevation={3} sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" gutterBottom>Create New Invoice</Typography>
        <form onSubmit={handleSubmit}>
          <TextField
            label="Invoice Number"
            name="invoiceNumber"
            value={formData.invoiceNumber}
            onChange={handleChange}
            fullWidth
            margin="normal"
            required
          />
          
          <TextField
            label="Customer Name"
            name="customerName"
            value={formData.customerName}
            onChange={handleChange}
            fullWidth
            margin="normal"
            required
          />
          
          <TextField
            label="Customer Address"
            name="customerAddress"
            value={formData.customerAddress}
            onChange={handleChange}
            fullWidth
            margin="normal"
            multiline
            rows={3}
          />
          
          <TextField
            label="Customer Phone"
            name="customerPhone"
            value={formData.customerPhone}
            onChange={handleChange}
            fullWidth
            margin="normal"
          />
          
          <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Invoice Items</Typography>
          {formData.items.map((item, index) => (
            <Box key={index} sx={{ display: 'flex', gap: 2, mb: 2 }}>
              <TextField
                label="Description"
                name="description"
                value={item.description}
                onChange={(e) => handleItemChange(index, e)}
                sx={{ flex: 2 }}
                required
              />
              <TextField
                label="Quantity"
                name="quantity"
                type="number"
                value={item.quantity}
                onChange={(e) => handleItemChange(index, e)}
                sx={{ flex: 1 }}
                required
              />
              <TextField
                label="Price"
                name="price"
                type="number"
                value={item.price}
                onChange={(e) => handleItemChange(index, e)}
                sx={{ flex: 1 }}
                required
              />
              <Button 
                onClick={() => removeItem(index)}
                variant="outlined"
                color="error"
                sx={{ flex: 0.5 }}
              >
                Remove
              </Button>
            </Box>
          ))}
          <Button 
            onClick={addItem}
            variant="outlined"
            startIcon={<AddIcon />}
            sx={{ mb: 2 }}
          >
            Add Item
          </Button>
          
          <TextField
            label="Tax (%)"
            name="tax"
            type="number"
            value={formData.tax}
            onChange={handleChange}
            fullWidth
            margin="normal"
          />
          
          <TextField
            label="Discount"
            name="discount"
            type="number"
            value={formData.discount}
            onChange={handleChange}
            fullWidth
            margin="normal"
          />
          
          <TextField
            label="Notes"
            name="notes"
            value={formData.notes}
            onChange={handleChange}
            fullWidth
            margin="normal"
            multiline
            rows={3}
          />
          
          <Box sx={{ mt: 2, mb: 2 }}>
            <Typography>Subtotal: ${formData.subtotal.toFixed(2)}</Typography>
            <Typography>Tax: ${(formData.subtotal * (formData.tax / 100)).toFixed(2)}</Typography>
            <Typography>Discount: ${formData.discount.toFixed(2)}</Typography>
            <Typography variant="h6">Total: ${formData.total.toFixed(2)}</Typography>
          </Box>
          
          <Button 
            type="submit" 
            variant="contained" 
            startIcon={<SaveIcon />}
            sx={{ mr: 2 }}
          >
            Save Invoice
          </Button>
          <Button 
            onClick={handlePreview}
            variant="outlined"
            startIcon={<PrintIcon />}
          >
            Preview
          </Button>
        </form>
      </Paper>

      <Paper elevation={3} sx={{ p: 3 }}>
        <Typography variant="h6" gutterBottom>Recent Invoices</Typography>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Invoice #</TableCell>
                <TableCell>Customer</TableCell>
                <TableCell>Date</TableCell>
                <TableCell>Total</TableCell>
                <TableCell>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {invoices.map(invoice => (
                <TableRow key={invoice._id}>
                  <TableCell>{invoice.invoiceNumber}</TableCell>
                  <TableCell>{invoice.customerName}</TableCell>
                  <TableCell>{new Date(invoice.date).toLocaleDateString()}</TableCell>
                  <TableCell>${invoice.total.toFixed(2)}</TableCell>
                  <TableCell>
                    <Button 
                      onClick={() => {
                        setFormData({
                          ...invoice,
                          items: invoice.items.map(item => ({
                            ...item,
                            quantity: parseFloat(item.quantity),
                            price: parseFloat(item.price)
                          }))
                        });
                        setPreviewOpen(true);
                      }}
                    >
                      View
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      <Dialog 
        open={previewOpen} 
        onClose={() => setPreviewOpen(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>Invoice Preview</DialogTitle>
        <DialogContent>
          <InvoicePreview invoice={formData} />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setPreviewOpen(false)}>Close</Button>
          <Button 
            onClick={() => window.print()}
            startIcon={<PrintIcon />}
          >
            Print
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
};

export default InvoiceManager;
